Translate("esMX", "darnassus", {
	title = "Darnassus",
	sections = {
		{
			title = "Resumen",
			text = [=[Darnassus es la capital de los {link:night-elves}elfos de la noche{/link}, una ciudad de madera viva y agua iluminada por la luna en las altas ramas de {link:teldrassil}Teldrassil{/link}. Sus salas han crecido en lugar de haber sido construidas. Sus bancales se abren a jardines y estanques tranquilos, y el {link:temple-of-the-moon}Templo de la Luna{/link} brilla en su corazón. Es una ciudad joven de un pueblo antiguo. Los kaldorei la levantaron tras la {link:third-war}Tercera Guerra{/link}, cuando habían perdido su inmortalidad y su antiguo hogar en el {link:mount-hyjal}Monte Hyjal{/link} había quedado lleno de cicatrices, y quisieron que fuera un nuevo comienzo.]=],
		},
		{
			title = "Orígenes",
			text = [=[Cuando terminó la guerra contra la {link:burning-legion}Legión Ardiente{/link}, el archidruida {link:fandral-staghelm}Fandral Staghelm{/link} y sus druidas hicieron crecer {link:teldrassil}Teldrassil{/link} más allá de la costa norte. Darnassus se alzó en su copa. Las sacerdotisas de Elune establecieron allí su templo, los druidas su enclave y las {link:sentinels}Centinelas{/link} sus barracones. Desde la {link:rut-theran-village}Aldea Rut'theran{/link}, muy abajo, un portal lleva a los viajeros hasta la ciudad.]=],
		},
		{
			title = "El presente",
			text = [=[Dos líderes residen en Darnassus. La suma sacerdotisa {link:tyrande-whisperwind}Tyrande Whisperwind{/link} gobierna la ciudad y a su pueblo según la voluntad de Elune. {link:fandral-staghelm}Fandral Staghelm{/link} dirige a los druidas durante la larga ausencia de {link:malfurion-stormrage}Malfurion Stormrage{/link}, que no ha regresado del {link:emerald-dream}Sueño Esmeralda{/link}. Tyrande pide a su pueblo que respete el rango de Fandral, pero le recuerda que los asuntos de Darnassus son solo suyos. Fandral, por su parte, no confía en nadie fuera de su enclave. Él y el guardián {link:keeper-remulos}Remulos{/link} del {link:moonglade}Claro de la Luna{/link} se sospechan mutuamente de engaño, y los males del Árbol del Mundo siguen sin curarse. Las {link:sentinels}Centinelas{/link} vigilan de cerca la propia ciudad, pues algo va mal en {link:teldrassil}Teldrassil{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Las sacerdotisas de Elune.{/b} Cuidan el {link:temple-of-the-moon}Templo de la Luna{/link} y sanan a los {link:night-elves}kaldorei{/link}.
• {b}Los druidas del {link:cenarion-circle}Círculo Cenarion{/link}.{/b} Estudian en el {link:cenarion-enclave}Enclave Cenarion{/link} bajo el archidruida.
• {b}Las {link:sentinels}Centinelas{/link}.{/b} Las mujeres guerreras que guardan la ciudad y los bosques de más allá.
• {b}Aliados de la {link:alliance}Alianza{/link}.{/b} Eruditos enanos de la {link:explorers-league}Liga de Expedicionarios{/link} y enviados del {link:argent-dawn}Alba Argenta{/link} han llegado a la ciudad.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}La fundación.{/b} La ciudad se levantó en las ramas del nuevo Árbol del Mundo tras la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}.
• {b}Las pozas de la luna.{/b} Los druidas de la ciudad se sirven de las pozas de la luna de {link:teldrassil}Teldrassil{/link}, y los mensajeros suben frascos de su agua desde {link:shadowglen}Cañada Umbría{/link}, {link:dolanaar}Dolanaar{/link} y {link:the-oracle-glade}El Claro del Oráculo{/link}.
• {b}La ruptura con el {link:moonglade}Claro de la Luna{/link}.{/b} El archidruida y el guardián {link:keeper-remulos}Remulos{/link} se han distanciado, y los druidas de la ciudad sirven al Círculo bajo una nube de sospecha.
• {b}El presente.{/b} Los {link:night-elves}kaldorei{/link} se han unido a la {link:alliance}Alianza{/link}, y héroes de todos los pueblos recorren ahora los bancales de Darnassus.]=],
		},
		{
			title = "Saber de la ciudad",
			text = [=[• Una fuente en el corazón del {link:temple-of-the-moon}Templo de la Luna{/link} contiene agua sagrada de la que se dice que purifica lo que toca.
• El árbol del archidruida se alza en el {link:cenarion-enclave}Enclave Cenarion{/link}, y bajo él corren túneles.
• Los druidas de Darnassus estudian tierra traída del lejano {link:un-goro-crater}Cráter de Un'Goro{/link}, y cultivan en ella hierbas cuya naturaleza aún no comprenden.]=],
		},
	},
})

Translate("esMX", "temple-of-the-moon", {
	title = "Templo de la Luna",
	aliases = { "Jardines del Templo", "Los Jardines del Templo" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Templo de la Luna se alza entre Los Jardines del Templo, en el sur de {link:darnassus}Darnassus{/link}. Es la casa de Elune y la sede de la suma sacerdotisa. {link:tyrande-whisperwind}Tyrande Whisperwind{/link} celebra audiencia en su sala superior. Abajo, las sacerdotisas enseñan a los jóvenes y sanan a los heridos, y en su centro brota una fuente de agua sagrada. Las ofrendas depositadas en esa fuente se entregan a la diosa. Las {link:sentinels}Centinelas{/link} guardan sus puertas y rezan allí a diario, pues una cazadora de Elune debe esgrimir los dones de su diosa tanto como su hoja.]=],
		},
	},
})

Translate("esMX", "cenarion-enclave", {
	title = "Enclave Cenarion",
	sections = {
		{
			title = "Resumen",
			text = [=[El Enclave Cenarion es el barrio de los druidas, en el norte de {link:darnassus}Darnassus{/link}. Aquí crece el gran árbol del archidruida {link:fandral-staghelm}Fandral Staghelm{/link}, donde estudia los males de {link:teldrassil}Teldrassil{/link} con su segundo, {link:mathrengyl-bearwalker}Mathrengyl Bearwalker{/link}, en el piso de abajo. Druidas como {link:rellian-greenspyre}Rellian Greenspyre{/link} recorren sus senderos. Los cazadores y los pícaros también tienen aquí sus salas. Detrás del árbol del archidruida, montones de tierra extraña de tierras lejanas esperan a ser clasificados, y unos túneles bajan a las profundidades bajo el Enclave.]=],
		},
	},
})

Translate("esMX", "warriors-terrace", {
	title = "Bancal del Guerrero",
	sections = {
		{
			title = "Resumen",
			text = [=[El Bancal del Guerrero se encuentra en el este de {link:darnassus}Darnassus{/link}. Aquí los guerreros de los {link:night-elves}kaldorei{/link} se entrenan con maestros como Elanaria y Arias'ta Bladesinger, y aquí la comandante {link:thyn-tel-bladeweaver}Thyn'tel Bladeweaver{/link} lleva los asuntos de las {link:sentinels}Centinelas{/link}. Las pertenencias de las Centinelas desaparecidas se guardan en su barracón hasta que regresen. Una guerrera que quiera aprender más debe demostrar primero su determinación contra los enemigos del árbol.]=],
		},
	},
})

Translate("esMX", "craftsmens-terrace", {
	title = "Bancal del Artesano",
	sections = {
		{
			title = "Resumen",
			text = [=[El Bancal del Artesano se encuentra en el nordeste de {link:darnassus}Darnassus{/link}. Peleteros, sastres y otros artesanos de los {link:night-elves}kaldorei{/link} tienen aquí sus talleres, y la posada de la ciudad ofrece descanso a viajeros de todas las tierras. Enviados del {link:argent-dawn}Alba Argenta{/link} se han instalado entre los artesanos. Aquí se reúne también la tela de la {link:alliance}Alianza{/link}, para las necesidades de la guerra que se avecina.]=],
		},
	},
})

Translate("esMX", "tradesmens-terrace", {
	title = "Bancal de los Mercaderes",
	sections = {
		{
			title = "Resumen",
			text = [=[El Bancal de los Mercaderes se encuentra en el este de {link:darnassus}Darnassus{/link}, entre los jardines y el {link:warriors-terrace}Bancal del Guerrero{/link}. Es el mercado de la ciudad. Mercaderes de comida, telas, armas y bienes generales tienen sus puestos a lo largo de sus senderos sinuosos, y las noticias del bosque de abajo corren deprisa entre ellos. Es el lugar más concurrido de Darnassus, y aun así más tranquilo que cualquier mercado de las tierras humanas.]=],
		},
	},
})

Translate("esMX", "tyrande-whisperwind", {
	title = "Tyrande Whisperwind",
	subtitle = "Suma sacerdotisa de Elune",
	found = "La sala superior del Templo de la Luna",
	hint = [=[Suba a la sala superior del Templo de la Luna y busque a la suma sacerdotisa.]=],
	allegiance = "Elfos de la noche · Hermandad de Elune · Centinelas",
	aliases = { "Tyrande", "Suma sacerdotisa Tyrande Whisperwind" },
	sections = {
		{
			title = "Resumen",
			text = [=[Tyrande Whisperwind es la suma sacerdotisa de Elune y la líder de los elfos de la noche. Durante diez mil años ha protegido a su pueblo, primero en las ruinas de su antiguo imperio y ahora en las ramas de {link:teldrassil}Teldrassil{/link}. Es la amada de {link:malfurion-stormrage}Malfurion Stormrage{/link}, y espera su regreso. Gobierna {link:darnassus}Darnassus{/link} con firmeza, y es conocida por su bondad.]=],
		},
		{
			title = "Importancia",
			text = [=[Tyrande es el vínculo vivo entre los {link:night-elves}kaldorei{/link} de antaño y los kaldorei de hoy. Luchó en la {link:war-of-the-ancients}Guerra de los Ancestros{/link} y en la {link:third-war}Tercera Guerra{/link}. Bajo su mando, las {link:sentinels}Centinelas{/link} se convirtieron en el escudo de su pueblo, y bajo su mando los elfos de la noche se han unido a la {link:alliance}Alianza{/link}.]=],
		},
		{
			title = "Historia",
			text = [=[Tyrande era novicia de la {link:syndicate}Hermandad{/link} de Elune en los días de la {link:queen-azshara}reina Azshara{/link}. Los hermanos gemelos {link:malfurion-stormrage}Malfurion{/link} e {link:illidan-stormrage}Illidan Stormrage{/link} la amaban, y ella eligió a Malfurion. Cuando llegó la {link:burning-legion}Legión Ardiente{/link}, luchó a su lado, y llegó a dirigir la Hermandad en aquella guerra. Tras el {link:great-sundering}Gran Fractura{/link}, mientras los druidas dormían en el {link:emerald-dream}Sueño Esmeralda{/link}, ella y sus sacerdotisas velaron por los bosques durante largos siglos.

Cuando la Legión regresó y los humanos y los orcos llegaron a {link:kalimdor}Kalimdor{/link}, Tyrande despertó a los druidas dormidos de sus túmulos. Liberó a Illidan de su prisión, en contra de los deseos de su amado. En la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, sus {link:sentinels}Centinelas{/link} lucharon junto a humanos y orcos hasta que {link:archimonde}Archimonde{/link} cayó.]=],
		},
		{
			title = "En el presente",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} ha vuelto a entrar en el Sueño, y nadie sabe qué ha sido de él. Tyrande dirige sola a los {link:night-elves}kaldorei{/link}. Respeta a {link:fandral-staghelm}Fandral Staghelm{/link} como archidruida, pero no le deja olvidar que su dominio es el druidismo, mientras que el de ella es su pueblo entero. Sus sacerdotisas y {link:sentinels}Centinelas{/link} le traen noticias de todos los bosques de {link:kalimdor}Kalimdor{/link}, y ella misma las escucha. Quienes llegan a su templo con hazañas hechas por su pueblo la encuentran agradecida y generosa, y pronta a pedirles que compartan sus relatos con los jóvenes.]=],
		},
	},
	chapters = {
		{
			title = "El agua de las pozas de la luna",
			hint = [=[Lleve lo que queda del agua de las pozas de la luna a la suma sacerdotisa.]=],
			text = [=[Las últimas gotas del agua de las pozas de la luna llegaron a Tyrande en un recipiente ceremonial, después de que el archidruida lo hubiera desechado. Ella dio las gracias al portador, pues cada gota estaba bendecida por Elune. También habló, breve y secamente, de {link:fandral-staghelm}Fandral{/link}: había hecho mucho en ausencia de {link:malfurion-stormrage}Malfurion{/link}, pero no era Malfurion.]=],
		},
		{
			title = "Noticias de las tierras salvajes",
			hint = [=[Lleve a la suma sacerdotisa noticias de sus sacerdotisas y exploradoras en tierras lejanas.]=],
			text = [=[Las noticias llegan al templo desde todos los rincones de {link:kalimdor}Kalimdor{/link}: de las {link:sentinels}Centinelas{/link} del {link:stonetalon-mountains}Espolón{/link} y de la sacerdotisa {link:jer-kai-moonweaver}Jer'kai{/link}, que combate a {link:grimtotem-clan}los Tótem Siniestro{/link} en {link:feralas}Feralas{/link}. Tyrande escucha cada relato en persona, y envía a sus exploradoras adonde se las necesita.]=],
		},
	},
	mentions = {
		{ text = "Recepción de Tyrande" },
		{ text = "Impartir justicia" },
		{ text = "Explorar la {link:alliance}Alianza{/link}" },
		{ text = "La corona de la tierra" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "su amado" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "el hermano al que liberó" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "archidruida de su pueblo" },
		{ id = "sentinels", name = "Centinelas", note = "sus guardianas" },
		{ id = "priestess-a-moora", name = "Sacerdotisa A'moora", note = "sirve en su templo" },
	},
})

Translate("esMX", "fandral-staghelm", {
	title = "Fandral Staghelm",
	subtitle = "Archidruida de Darnassus",
	found = "Su árbol en el Enclave Cenarion",
	hint = "Busque al archidruida en su árbol del Enclave Cenarion.",
	allegiance = "Elfos de la noche · Círculo Cenarion",
	aliases = { "Fandral", "Archidruida Fandral Staghelm" },
	sections = {
		{
			title = "Resumen",
			text = [=[Fandral Staghelm es el archidruida de los elfos de la noche. Cuando {link:malfurion-stormrage}Malfurion Stormrage{/link} desapareció tras la {link:third-war}Tercera Guerra{/link}, Fandral asumió el liderazgo de los druidas y decidió que su pueblo reconstruiría. Hizo crecer {link:teldrassil}Teldrassil{/link}, el nuevo Árbol del Mundo, y aún trabaja para sanarlo por completo. Es orgulloso, impaciente e incansable, y no confía en nadie más que en sí mismo para terminar la obra.]=],
		},
		{
			title = "Importancia",
			text = [=[Pocos {link:night-elves}kaldorei{/link} han dado forma a la era presente más que Fandral. {link:darnassus}Darnassus{/link} se alza en el árbol que él levantó. Sin embargo, el árbol es imperfecto, la inmortalidad que buscaba no ha vuelto y su disputa con el {link:moonglade}Claro de la Luna{/link} divide al {link:cenarion-circle}Círculo Cenarion{/link}.]=],
		},
		{
			title = "Historia",
			text = [=[Tras la {link:battle-of-mount-hyjal}Batalla del Monte Hyjal{/link}, {link:nordrassil}Nordrassil{/link} humeaba y los druidas se habían quedado sin líder. Fandral convenció al Círculo de los Ancianos de {link:darkshore}Costa Oscura{/link} de que los {link:night-elves}kaldorei{/link} debían reconstruir y recuperar su inmortalidad. Con la aprobación del Círculo, él y los druidas más poderosos hicieron crecer {link:teldrassil}Teldrassil{/link} frente a la costa norte. Después pidió a los dragones su bendición. Nozdormu se la negó y le reprochó su arrogancia, y {link:alexstrasza}Alexstrasza{/link} también se negó. Sin sus dones, el árbol ha crecido imperfecto e imprevisible.]=],
		},
		{
			title = "En el presente",
			text = [=[Fandral trabaja sin descanso en los problemas del árbol, y los llama un yugo del que desea librarse. Cree que solo él sacó a su pueblo de la oscuridad, y llama propaganda a las palabras del {link:moonglade}Claro de la Luna{/link}. El guardián {link:keeper-remulos}Remulos{/link} y él se sospechan mutuamente. Hasta su propio segundo admite que el aire entre ellos está cargado de desconfianza.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Hizo crecer {link:teldrassil}Teldrassil{/link}, el nuevo Árbol del Mundo.
• Estudia las tierras de {link:un-goro-crater}Un'Goro{/link} y la hierba morrowgrain.
• Envía mensajes a {link:onu}Onu{/link}, el Anciano del Saber de {link:darkshore}Costa Oscura{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Fandral antes de la {link:third-war}Tercera Guerra{/link}. Esta entrada solo recoge sus hazañas desde entonces.]=],
		},
	},
	chapters = {
		{
			title = "La corona de la tierra",
			hint = [=[Lleve al archidruida el agua de las pozas de la luna de Teldrassil.]=],
			text = [=[El recipiente llenado en las pozas de la luna del árbol llegó por fin a Fandral. Él se quejó de que había tardado demasiado y de que los mensajeros no eran los más fiables. Después habló del peso de los problemas de {link:teldrassil}Teldrassil{/link} sobre sus hombros.]=],
		},
		{
			title = "El informe del Oráculo",
			hint = "Entregue al archidruida el informe del Árbol del Oráculo.",
			text = [=[El Árbol del Oráculo llevaba mucho tiempo en silencio. Su informe dijo a Fandral que algunos de los males del árbol habían disminuido mientras otros habían crecido. Él temió en voz alta que su obra nunca llegaría a terminarse.]=],
		},
		{
			title = "La nueva frontera",
			hint = "Responda a la llamada de ayuda del Círculo Cenarion.",
			text = [=[Cuando el {link:moonglade}Claro de la Luna{/link} pidió ayuda en el lejano oeste, Fandral pasó el asunto a {link:mathrengyl-bearwalker}Mathrengyl{/link} de mala gana, y dio una advertencia propia: no ser un necio que cree las palabras del Claro de la Luna.]=],
		},
	},
	mentions = {
		{ text = "La corona de la tierra" },
		{ text = "{link:teldrassil}Teldrassil{/link}" },
		{ text = "La Arboleda de los Ancianos" },
		{ text = "La nueva frontera" },
		{ text = "Tierra de {link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Investigación del morrowgrain" },
		{ text = "Las fieras lunares de Elune" },
		{ text = "La corona de la tierra, el frasco que desechó" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "dirige a los druidas en su lugar" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "gobierna la ciudad que él levantó" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "su segundo" },
		{ id = "corithras-moonrage", name = "Corithras Moonrage", note = "le envía el agua de las pozas de la luna" },
	},
})

