	sections = {
		{
			title = "Resumen",
			text = [=[Mathrengyl Bearwalker es el asistente directo del archidruida, uno de los druidas más sabios de {link:teldrassil}Teldrassil{/link}. Instruye a los jóvenes druidas y los envía al {link:moonglade}Claro de la Luna{/link}, sean cuales sean las disputas de sus mayores. Es sincero sobre esas disputas. La desconfianza entre {link:darnassus}Darnassus{/link} y el Claro de la Luna es real, admite, pero el deber hacia el Círculo permanece.]=],
