	},
	mentions = {
		{ text = "Atender la llamada" },
		{ text = "{link:moonglade}Claro de la Luna{/link}" },
		{ text = "La nueva frontera" },
		{ text = "{link:rabine-saturna}Rabine Saturna{/link}" },
		{ text = "Investigación del morrowgrain" },
		{ text = "A {link:darnassus}Darnassus{/link}" },
