	},
})

Translate("esMX", "sentinels", {
	title = "Centinelas",
	sections = {
		{
			title = "Resumen",
			text = [=[Las Centinelas son las guerreras de los {link:night-elves}elfos de la noche{/link}. Durante miles de años han guardado los bosques de {link:kalimdor}Kalimdor{/link}, y responden ante la suma sacerdotisa de Elune. La mayoría son mujeres, cazadoras que esgrimen los dones de la diosa tanto como la guja y el arco.]=],
		},
		{
			title = "Orígenes",
			text = [=[Tras el {link:great-sundering}Gran Fractura{/link}, mientras los druidas dormían en el {link:emerald-dream}Sueño Esmeralda{/link}, las sacerdotisas de Elune y sus guerreras velaron por los {link:night-elves}kaldorei{/link}. A lo largo de aquellas largas eras, las Centinelas se convirtieron en el escudo de su pueblo.]=],
		},
		{
			title = "En el presente",
			text = [=[Las Centinelas montan guardia en cada aldea de {link:teldrassil}Teldrassil{/link} y en cada camino. Guardan el Árbol del Oráculo, llevan sus mensajes a {link:darnassus}Darnassus{/link} y combaten a los {link:gnarlpine-furbolgs}Tuercepinos{/link} y a las arpías. Más allá del árbol mantienen puestos en {link:darkshore}Costa Oscura{/link}, {link:ashenvale}Vallefresno{/link} y {link:feralas}Feralas{/link}. La {link:shandris-feathermoon}general Feathermoon{/link} se asegura de que cada una tenga tiempo para rezar, y en Darnassus vigilan la propia ciudad, pues temen que algo vaya mal.]=],
		},
	},
})
